create temporary table _mmda (slug text, region_slug text, name text, capital text) on commit drop;

update public.places set slug = 'akatsi-south' where slug = 'akatsi-south-municipal';

update public.places p
   set name = m.name, capital = m.capital,
       url_path = m.region_slug || '/' || m.slug,
       data_confidence = 'Sourced',
       reference_source = 'Inter-Ministerial Coordinating Committee on Decentralisation (imccod.gov.gh/mmdas)',
       reference_verified = date '2026-08-29'
  from _mmda m
 where p.slug = m.slug and p.type_slug = 'district';

select m.slug, 'district', m.region_slug || '/' || m.slug, m.name, m.capital, 'Sourced',
       'Inter-Ministerial Coordinating Committee on Decentralisation (imccod.gov.gh/mmdas)', date '2026-08-29'
  from _mmda m
 where not exists (select 1 from public.places p where p.slug = m.slug);

select m.region_slug, m.slug, 'administrative'
  from _mmda m
 where not exists (select 1 from public.place_links l where l.child_slug = m.slug and l.link_type_slug = 'administrative');
